import java.nio.file.Files
import java.nio.file.Paths

fun read(name: String) = Files.newInputStream(Paths.get(name)).use { it.readAllBytes() }

import java.nio.file.Files
import java.nio.file.Path

fun write(path: Path, data: ByteArray) = Files.newOutputStream(path).use { it.write(data) }

import java.nio.file.Files
import java.nio.file.Path

fun readAll(paths: List<Path>) = paths.map {
    Files.newInputStream(it).use { s -> s.readAllBytes() } // bad: unbuffered per element
}

import java.nio.file.Files
import java.nio.file.Path

fun read(path: Path) = Files.newBufferedReader(path).use { it.readText() }
